import{_ as o,a0 as i,w as m,s as l,I as t,x as d,a1 as n,A as p,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse(`{"title":"在 Linux 下使用 RAID（八）：当软件 RAID 故障时如何恢复和重建数据 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 下使用 RAID（八）：当软件 RAID 故障时如何恢复和重建数据 | LCTT (RAID) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 下使用 RAID（八）：当软件 RAID 故障时如何恢复和重建数据 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 下使用 RAID（八）：当软件 RAID 故障时如何恢复和重建数据 | LCTT (RAID) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"RAID/Part 8 - How to Recover Data and Rebuild Failed Software RAID's","title":"在 Linux 下使用 RAID（八）：当软件 RAID 故障时如何恢复和重建数据","tag":"RAID","desc":""},"relativePath":"RAID/Part 8 - How to Recover Data and Rebuild Failed Software RAID's.md","filePath":"[post].md"}`),s={name:"RAID/Part 8 - How to Recover Data and Rebuild Failed Software RAID's.md"};function R(u,e,A,D,I,c){const a=i("Link");return m(),l("div",null,[e[22]||(e[22]=t("h1",{id:"在-linux-下使用-raid-八-当软件-raid-故障时如何恢复和重建数据",tabindex:"-1"},[d("在 Linux 下使用 RAID（八）：当软件 RAID 故障时如何恢复和重建数据 "),t("a",{class:"header-anchor",href:"#在-linux-下使用-raid-八-当软件-raid-故障时如何恢复和重建数据","aria-label":"Permalink to “在 Linux 下使用 RAID（八）：当软件 RAID 故障时如何恢复和重建数据”"},"​")],-1)),t("p",null,[e[1]||(e[1]=d("在阅读过 ",-1)),n(a,{href:"https://linux.cn/article-6085-1.html"},{default:p(()=>[...e[0]||(e[0]=[d("RAID 系列",-1)])]),_:1}),e[2]||(e[2]=d(" 前面的文章后你已经对 RAID 比较熟悉了。回顾前面几个软件 RAID 的配置，我们对每一个都做了详细的解释，使用哪一个取决与你的具体情况。",-1))]),e[23]||(e[23]=t("p",null,[t("img",{src:"http://www.tecmint.com/wp-content/uploads/2015/10/Recover-Rebuild-Failed-Software-RAID.png",alt:"Recover Rebuild Failed Software RAID's"})],-1)),e[24]||(e[24]=t("p",null,[t("em",null,"恢复并重建故障的软件 RAID - 第8部分")],-1)),e[25]||(e[25]=t("p",null,"在本文中，我们将讨论当一个磁盘发生故障时如何重建软件 RAID 阵列并且不会丢失数据。为方便起见，我们仅考虑RAID 1 的配置 - 但其方法和概念适用于所有情况。",-1)),e[26]||(e[26]=t("h4",{id:"raid-测试方案",tabindex:"-1"},[d("RAID 测试方案 "),t("a",{class:"header-anchor",href:"#raid-测试方案","aria-label":"Permalink to “RAID 测试方案”"},"​")],-1)),t("p",null,[e[4]||(e[4]=d("在进一步讨论之前，请确保你已经配置好了 RAID 1 阵列，可以按照本系列第3部分提供的方法：",-1)),n(a,{href:"https://linux.cn/article-6093-1.html"},{default:p(()=>[...e[3]||(e[3]=[d("在 Linux 中如何创建 RAID 1（镜像）",-1)])]),_:1}),e[5]||(e[5]=d("。",-1))]),e[27]||(e[27]=r(`<p>在目前的情况下，仅有的变化是：</p><ol><li>使用不同版本 CentOS（v7），而不是前面文章中的（v6.5）。</li><li>磁盘容量发生改变， /dev/sdb 和 /dev/sdc（各8GB）。</li></ol><p>此外，如果 SELinux 设置为 enforcing 模式，你需要将相应的标签添加到挂载 RAID 设备的目录中。否则，当你试图挂载时，你会碰到这样的警告信息：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/SELinux-RAID-Mount-Error.png" alt="SELinux RAID Mount Error"></p><p><em>启用 SELinux 时 RAID 挂载错误</em></p><p>通过以下命令来解决:</p><pre><code># restorecon -R /mnt/raid1
</code></pre><h3 id="配置-raid-监控" tabindex="-1">配置 RAID 监控 <a class="header-anchor" href="#配置-raid-监控" aria-label="Permalink to “配置 RAID 监控”">​</a></h3><p>存储设备损坏的原因很多（尽管固态硬盘大大减少了这种情况发生的可能性），但不管是什么原因，可以肯定问题随时可能发生，你需要准备好替换发生故障的部分，并确保数据的可用性和完整性。</p><p>首先建议是。虽然你可以查看 <code>/proc/mdstat</code> 来检查 RAID 的状态，但有一个更好的和节省时间的方法，使用监控 + 扫描模式运行 mdadm，它将警报通过电子邮件发送到一个预定义的收件人。</p><p>要这样设置，在 <code>/etc/mdadm.conf</code> 添加以下行：</p><pre><code>MAILADDR user@&lt;domain or localhost&gt;
</code></pre><p>我自己的设置如下：</p><pre><code>MAILADDR gacanepa@localhost
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/RAID-Monitoring-Email-Alerts.png" alt="RAID Monitoring Email Alerts"></p><p><em>监控 RAID 并使用电子邮件进行报警</em></p><p>要让 mdadm 运行在监控 + 扫描模式中，以 root 用户添加以下 crontab 条目：</p><pre><code>@reboot /sbin/mdadm --monitor --scan --oneshot
</code></pre><p>默认情况下，mdadm 每隔60秒会检查 RAID 阵列，如果发现问题将发出警报。你可以通过添加 <code>--delay</code> 选项到crontab 条目上面，后面跟上秒数，来修改默认行为（例如，<code>--delay</code> 1800意味着30分钟）。</p>`,19)),t("p",null,[e[7]||(e[7]=d("最后，确保你已经安装了一个邮件用户代理（MUA），如",-1)),n(a,{href:"http://www.tecmint.com/send-mail-from-command-line-using-mutt-command/"},{default:p(()=>[...e[6]||(e[6]=[d("mutt 或 mailx",-1)])]),_:1}),e[8]||(e[8]=d("。否则，你将不会收到任何警报。",-1))]),e[28]||(e[28]=r(`<p>在一分钟内，我们就会看到 mdadm 发送的警报。</p><h3 id="模拟和更换发生故障的-raid-存储设备" tabindex="-1">模拟和更换发生故障的 RAID 存储设备 <a class="header-anchor" href="#模拟和更换发生故障的-raid-存储设备" aria-label="Permalink to “模拟和更换发生故障的 RAID 存储设备”">​</a></h3><p>为了给 RAID 阵列中的存储设备模拟一个故障，我们将使用 <code>--manage</code> 和 <code>--set-faulty</code> 选项，如下所示：</p><pre><code># mdadm --manage --set-faulty /dev/md0 /dev/sdc1  
</code></pre><p>这将导致 /dev/sdc1 被标记为 faulty，我们可以在 /proc/mdstat 看到：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/Stimulate-Issue-with-RAID-Storage.png" alt="Stimulate Issue with RAID Storage"></p><p><em>在 RAID 存储设备上模拟问题</em></p><p>更重要的是，让我们看看是不是收到了同样的警报邮件：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/Email-Alert-on-Failed-RAID-Device.png" alt="Email Alert on Failed RAID Device"></p><p><em>RAID 设备故障时发送邮件警报</em></p><p>在这种情况下，你需要从软件 RAID 阵列中删除该设备：</p><pre><code># mdadm /dev/md0 --remove /dev/sdc1
</code></pre><p>然后，你可以直接从机器中取出，并将其使用备用设备来取代（/dev/sdd 中类型为 fd 的分区是以前创建的）：</p><pre><code># mdadm --manage /dev/md0 --add /dev/sdd1
</code></pre><p>幸运的是，该系统会使用我们刚才添加的磁盘自动重建阵列。我们可以通过标记 /dev/sdb1 为 faulty 来进行测试，从阵列中取出后，并确认 tecmint.txt 文件仍然在 /mnt/raid1 是可访问的：</p><pre><code># mdadm --detail /dev/md0
# mount | grep raid1
# ls -l /mnt/raid1 | grep tecmint
# cat /mnt/raid1/tecmint.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/Rebuilding-RAID-Array.png" alt="Confirm Rebuilding RAID Array"></p><p><em>确认 RAID 重建</em></p><p>上面图片清楚的显示，添加 /dev/sdd1 到阵列中来替代 /dev/sdc1，数据的重建是系统自动完成的，不需要干预。</p><p>虽然要求不是很严格，有一个备用设备是个好主意，这样更换故障的设备就可以在瞬间完成了。要做到这一点，先让我们重新添加 /dev/sdb1 和 /dev/sdc1：</p><pre><code># mdadm --manage /dev/md0 --add /dev/sdb1
# mdadm --manage /dev/md0 --add /dev/sdc1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/Replace-Failed-Raid-Device.png" alt="Replace Failed Raid Device"></p><p><em>取代故障的 Raid 设备</em></p><h3 id="从冗余丢失中恢复数据" tabindex="-1">从冗余丢失中恢复数据 <a class="header-anchor" href="#从冗余丢失中恢复数据" aria-label="Permalink to “从冗余丢失中恢复数据”">​</a></h3><p>如前所述，当一个磁盘发生故障时， mdadm 将自动重建数据。但是，如果阵列中的2个磁盘都故障时会发生什么？让我们来模拟这种情况，通过标记 /dev/sdb1 和 /dev/sdd1 为 faulty：</p><pre><code># umount /mnt/raid1
# mdadm --manage --set-faulty /dev/md0 /dev/sdb1
# mdadm --stop /dev/md0
# mdadm --manage --set-faulty /dev/md0 /dev/sdd1
</code></pre><p>此时尝试以同样的方式重新创建阵列就（或使用 <code>--assume-clean</code> 选项）可能会导致数据丢失，因此不到万不得已不要使用。</p><p>让我们试着从 /dev/sdb1 恢复数据，例如，在一个类似的磁盘分区（/dev/sde1 - 注意，这需要你执行前在/dev/sde 上创建一个 fd 类型的分区）上使用 <code>ddrescue</code>：</p><pre><code># ddrescue -r 2 /dev/sdb1 /dev/sde1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/Recovering-Raid-Array.png" alt="Recovering Raid Array"></p><p><em>恢复 Raid 阵列</em></p><p>请注意，到现在为止，我们还没有触及 /dev/sdb 和 /dev/sdd，这是 RAID 阵列的一部分分区。</p><p>现在，让我们使用 /dev/sde1 和 /dev/sdf1 来重建阵列：</p><pre><code># mdadm --create /dev/md0 --level=mirror --raid-devices=2 /dev/sd[e-f]1
</code></pre><p>请注意，在真实的情况下，你需要使用与原来的阵列中相同的设备名称，即设备失效后替换的磁盘的名称应该是 /dev/sdb1 和 /dev/sdc1。</p><p>在本文中，我选择了使用额外的设备来重新创建全新的磁盘阵列，是为了避免与原来的故障磁盘混淆。</p><p>当被问及是否继续写入阵列时，键入 Y，然后按 Enter。阵列被启动，你也可以查看它的进展：</p><pre><code># watch -n 1 cat /proc/mdstat
</code></pre><p>当这个过程完成后，你就应该能够访问 RAID 的数据：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/10/Raid-Content.png" alt="Confirm Raid Content"></p><p><em>确认 Raid 数据</em></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>在本文中，我们回顾了从 RAID 故障和冗余丢失中恢复数据。但是，你要记住，这种技术是一种存储解决方案，不能取代备份。</p><p>本文中介绍的方法适用于所有 RAID 中，其中的概念我将在本系列的最后一篇（RAID 管理）中涵盖它。</p><p>如果你对本文有任何疑问，随时给我们以评论的形式说明。我们期待倾听阁下的心声！</p><hr>`,46)),t("p",null,[e[10]||(e[10]=d("via: ",-1)),n(a,{href:"http://www.tecmint.com/recover-data-and-rebuild-failed-software-raid/"},{default:p(()=>[...e[9]||(e[9]=[d("http://www.tecmint.com/recover-data-and-rebuild-failed-software-raid/",-1)])]),_:1})]),t("p",null,[e[14]||(e[14]=d("作者：",-1)),n(a,{href:"http://www.tecmint.com/author/gacanepa/"},{default:p(()=>[...e[11]||(e[11]=[d("Gabriel Cánepa",-1)])]),_:1}),e[15]||(e[15]=d(" 译者：",-1)),n(a,{href:"https://github.com/strugglingyouth"},{default:p(()=>[...e[12]||(e[12]=[d("strugglingyouth",-1)])]),_:1}),e[16]||(e[16]=d(" 校对：",-1)),n(a,{href:"https://github.com/wxy"},{default:p(()=>[...e[13]||(e[13]=[d("wxy",-1)])]),_:1})]),t("p",null,[e[19]||(e[19]=d("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[17]||(e[17]=[d("LCTT",-1)])]),_:1}),e[20]||(e[20]=d(" 原创编译，",-1)),n(a,{href:"https://linux.cn/"},{default:p(()=>[...e[18]||(e[18]=[d("Linux中国",-1)])]),_:1}),e[21]||(e[21]=d(" 荣誉推出",-1))])])}const g=o(s,[["render",R]]);export{f as __pageData,g as default};
